const j = await jira.listItems();
const all = await items.list();
return {
 jira: j.map(i => i.gone ? i : ({id:i.id, type:i.issueType, s:i.summary, st:i.status.name, a:i.assignee?.name??null, p:i.points, lastC:i.comments.at(-1)?.body.slice(0,200)??null, d:i.description.slice(0,200)})),
 folders: all.filter(i=>i.id.startsWith("folder:")).map(i => i.gone ? i : ({id:i.id, t:i.title, x:i.text.slice(0,400)}))
};

